solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#ifdef __cplusplus
#include <atomic>
static std::atomic_bool factory_locked{false};
#else
#include <stdatomic.h>
static atomic_bool factory_locked = false;
#endif
static bool used[676000];
static unsigned issued;
static uint64_t fallback_state;
static void acquire_factory(void) {
#ifdef __cplusplus
    while (factory_locked.exchange(true, std::memory_order_acquire)) {
    }
#else
    while (atomic_exchange_explicit(&factory_locked, true, memory_order_acquire)) {
    }
#endif
}
static void release_factory(void) {
#ifdef __cplusplus
    factory_locked.store(false, std::memory_order_release);
#else
    atomic_store_explicit(&factory_locked, false, memory_order_release);
#endif
}
/* Prefer operating-system entropy; standard-library-only fallback is seeded
 * once from wall-clock time and an address, then advances a xorshift PRNG.
 * This exercise requires unpredictable assignment order, not security keys. */
static uint32_t random_number(FILE *entropy) {
    uint32_t value;
    if (entropy && fread(&value, sizeof(value), 1, entropy) == 1)
        return value;
    if (!fallback_state) {
        struct timespec now;
        timespec_get(&now, TIME_UTC);
        fallback_state = (uint64_t)now.tv_sec ^ ((uint64_t)now.tv_nsec << 32) ^
                         (uintptr_t)&fallback_state;
        if (!fallback_state)
            fallback_state = 0x9e3779b97f4a7c15ULL;
    }
    fallback_state ^= fallback_state >> 12;
    fallback_state ^= fallback_state << 25;
    fallback_state ^= fallback_state >> 27;
    return (uint32_t)((fallback_state * 2685821657736338717ULL) >> 32);
}
bool robot_create(robot *result) {
    acquire_factory();
    if (issued == 676000) {
        release_factory();
        return false;
    }
    FILE *entropy = fopen("/dev/urandom", "rb");
    unsigned identifier;
    do {
        identifier = random_number(entropy) % 676000;
    } while (used[identifier]);
    if (entropy)
        fclose(entropy);
    used[identifier] = true;
    ++issued;
    result->name[0] = (char)('A' + identifier / 26000);
    result->name[1] = (char)('A' + identifier / 1000 % 26);
    snprintf(result->name + 2, 4, "%03u", identifier % 1000);
    release_factory();
    return true;
}
bool robot_reset(robot *result) { return robot_create(result); }

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
static unsigned name_id(const char *name) {
    assert(strlen(name) == 5);
    assert(name[0] >= 'A' && name[0] <= 'Z' && name[1] >= 'A' && name[1] <= 'Z');
    for (int i = 2; i < 5; ++i)
        assert(name[i] >= '0' && name[i] <= '9');
    return (unsigned)(name[0] - 'A') * 26000 + (unsigned)(name[1] - 'A') * 1000 +
           (unsigned)(name[2] - '0') * 100 + (unsigned)(name[3] - '0') * 10 +
           (unsigned)(name[4] - '0');
}

int main(void) {
    robot first, second;
    assert(robot_create(&first) && robot_create(&second));
    assert(strcmp(first.name, second.name));
    char original[6];
    strcpy(original, first.name);
    assert(robot_reset(&first) && strcmp(original, first.name));
    /* Retain every assigned name, including retired names: a reset must not make
     * a name immediately available for another robot. */
    bool *seen = (bool *)calloc(676000, sizeof(bool));
    seen[name_id(original)] = true;
    seen[name_id(first.name)] = true;
    seen[name_id(second.name)] = true;
    unsigned previous = 0, first_difference = 0;
    bool constant_difference = true;
    for (unsigned i = 0; i < 2000; ++i) {
        robot next;
        assert(robot_create(&next));
        unsigned id = name_id(next.name);
        assert(!seen[id]);
        seen[id] = true;
        unsigned difference = (id + 676000 - previous) % 676000;
        if (i == 1)
            first_difference = difference;
        if (i > 1 && difference != first_difference)
            constant_difference = false;
        previous = id;
    }
    /* Regression for the old predictable affine permutation. Testing thousands
     * of differences avoids depending on a particular random first name. */
    assert(!constant_difference);
    for (unsigned i = 0; i < 1000; ++i) {
        assert(robot_reset(&first));
        unsigned id = name_id(first.name);
        assert(!seen[id]);
        seen[id] = true;
    }
    free(seen);

    return 0;
}
